#include <string>
#include <algorithm>
#include <iostream>

void sort_string(std::string& s) {
    // Uses s.begin() and s.end(), demonstrating invasive API
    std::sort(s.begin(), s.end());
}

int main() {
    std::string text = "zebra";
    sort_string(text);
    std::cout << text; // Output: abrez
}
